import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  // Root object for this UI element
  const root = new Group();
  root.name = config?.name ?? 'thumbnail-card';

  // Store internal resources for cleanup
  const resources = {
    gltf: null,
    hoverTimeline: null,
  };

  // Load the GLB mesh (materials are included in the asset)
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      resources.gltf = gltf;
      // Preserve original scaling/position from the GLB; adapter will handle placement
      root.add(gltf.scene);
    });
  }

  /* -------------------------------------------------
   * Interaction: hover lift (rise‑in) and click emit
   * ------------------------------------------------- */
  // Hover lift – rise‑in 0.15 units, using the preset timing (≈0.7s, power3.out)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    root.position,
    {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }
  );
  resources.hoverTimeline = hoverTimeline;

  // Attach event handlers to userData
  root.userData.handlers = {
    // Expected to be called with a boolean: true → hover enter, false → hover leave
    hover: (enter) => {
      if (enter) {
        hoverTimeline.play();
      } else {
        hoverTimeline.reverse();
      }
    },
    click: () => {
      // Emit the navigation/select event as specified
      ctx.emit('hub-home.select');
    },
  };

  // Cleanup routine – disposes GLTF resources and kills timelines
  root.userData.cleanup = () => {
    if (resources.hoverTimeline) {
      resources.hoverTimeline.kill();
      resources.hoverTimeline = null;
    }

    if (resources.gltf && resources.gltf.scene) {
      resources.gltf.scene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) {
            obj.geometry.dispose();
          }
          const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
          mats.forEach((mat) => {
            if (!mat) return;
            // Dispose textures used by the material
            ['map', 'normalMap', 'roughnessMap', 'metalnessMap', 'envMap', 'aoMap', 'emissiveMap'].forEach((prop) => {
              if (mat[prop]) {
                mat[prop].dispose();
              }
            });
            mat.dispose();
          });
        }
      });
    }
  };

  // No cinematic primitives to apply per spec
  // (If any were present, they would be invoked via ctx.primitives here.)

  return root;
}
